package com.csi;
import com.fasterxml.jackson.databind.JsonNode;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;
@RestController public class Intake {
 final Db db;final ApiController api;final Events events;final String secret;
 static final Map<String,String> TITLES=Map.of("SEC-01","비밀번호 평문 저장 후보","SEC-02","비밀번호에 빠른 범용 해시 적용 후보","SEC-03","고정 Salt 사용 후보","SEC-04","bcrypt 비용이 사내 최소 기준 미달","SEC-05","로그에 민감정보 노출 후보","POL-01","승인되지 않은 개인정보 필드 후보");
 static final Map<String,String> SEVERITY=Map.of("SEC-01","HIGH","SEC-02","HIGH","SEC-03","MEDIUM","SEC-04","MEDIUM","SEC-05","HIGH","POL-01","LOW");
 public Intake(Db db,ApiController api,Events events,@Value("${csi.integration-secret}")String secret){this.db=db;this.api=api;this.events=events;this.secret=secret;if(secret.length()<32)throw new IllegalStateException("Integration secret too short");}
 public static boolean validSignature(byte[] body,String timestamp,String signature,String secret,long now){try{if(Math.abs(now-Long.parseLong(timestamp))>300)return false;Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));mac.update((timestamp+".").getBytes(StandardCharsets.UTF_8));String expected=HexFormat.of().formatHex(mac.doFinal(body));return MessageDigest.isEqual(expected.getBytes(StandardCharsets.US_ASCII),signature.getBytes(StandardCharsets.US_ASCII));}catch(Exception e){return false;}}
 static String mask(String code){return code.replaceAll("(?s)\"\"\".*?\"\"\"|'''.*?'''", "\"[REDACTED]\"").replaceAll("(?s)/\\*.*?\\*/", "/* REDACTED */").replaceAll("//[^\\r\\n]*", "// REDACTED").replaceAll("\"(?:\\\\.|[^\"\\\\])*\"", "\"[REDACTED]\"").replaceAll("'(?:\\\\.|[^'\\\\])*'", "'[REDACTED]'").replaceAll("(?m)#[^\\r\\n]*", "# REDACTED");}
 @PostMapping("/api/integrations/github/scan-results") @Transactional public ResponseEntity<?> accept(HttpServletRequest request)throws Exception{
 byte[] raw=request.getInputStream().readNBytes(1_000_001);if(raw.length>1_000_000)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE);
 if(!validSignature(raw,request.getHeader("X-CSI-Timestamp"),request.getHeader("X-CSI-Signature"),secret,Instant.now().getEpochSecond()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"서명을 확인할 수 없습니다.");
 JsonNode root=db.json.readTree(raw);String repo=root.path("repository").asText(),sha=root.path("commitSha").asText(),branch=root.path("branch").asText(),run=root.path("workflowRunId").asText(),trigger=root.path("triggerType").asText();int attempt=root.path("runAttempt").asInt();
 if(!api.isAllowed(repo)||!sha.matches("[0-9a-f]{40}")||!run.matches("[0-9]{1,30}")||attempt<1||attempt>100||!branch.matches("[A-Za-z0-9_./-]{1,100}")||!Set.of("GITHUB_PUSH","WORKFLOW_DISPATCH","LOCAL_DEMO").contains(trigger)||!root.path("findings").isArray()||root.path("findings").size()>300||!root.path("scannerSuccess").asBoolean())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"검사 메타데이터 또는 분석 완료 상태를 확인하세요.");
 var p=db.one("SELECT p.*,pp.version,pp.policy FROM projects p JOIN project_policies pp ON pp.project_id=p.id WHERE repository=?",repo);UUID project=UUID.fromString((String)p.get("id"));UUID id=UUID.randomUUID();String url=trigger.equals("LOCAL_DEMO")?null:"https://github.com/"+repo+"/actions/runs/"+run;
 int inserted=db.jdbc.update("INSERT INTO scans(id,project_id,repository,branch,commit_sha,workflow_run_id,run_attempt,run_url,trigger_type,status,policy_version,policy) VALUES(?,?,?,?,?,?,?,?,?,'QUEUED',?,?::jsonb) ON CONFLICT(repository,workflow_run_id,run_attempt) DO NOTHING",id,project,repo,branch,sha,run,attempt,url,trigger,p.get("version"),db.encode(p.get("policy")));
 if(inserted==0){var old=db.one("SELECT id,commit_sha,branch FROM scans WHERE repository=? AND workflow_run_id=? AND run_attempt=?",repo,run,attempt);if(!sha.equals(old.get("commitSha"))||!branch.equals(old.get("branch")))throw new ResponseStatusException(HttpStatus.CONFLICT,"이벤트 식별자가 다른 커밋에 사용되었습니다.");return ResponseEntity.accepted().body(Map.of("scanId",old.get("id"),"duplicate",true));}
 Set<String> fingerprints=new HashSet<>();for(var f:root.path("findings")){String rule=f.path("ruleId").asText(),file=f.path("filePath").asText(),fp=f.path("fingerprint").asText(),code=f.path("maskedCodeEvidence").asText();int start=f.path("startLine").asInt(),end=f.path("endLine").asInt();if(!TITLES.containsKey(rule)||file.startsWith("/")||file.contains("..")||!file.matches("[A-Za-z0-9_./$-]+\\.(java|py)")||file.length()>500||start<1||end<start||end-start>100||!fp.matches("[a-f0-9]{64}")||code.length()>8000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"유효하지 않은 정적 분석 근거입니다.");if(!fingerprints.add(fp))continue;UUID fid=UUID.randomUUID();String evidence=rule.equals("POL-01")?"INSUFFICIENT_EVIDENCE":"SUSPECTED";db.jdbc.update("INSERT INTO findings(id,scan_id,rule_id,title,category,severity,file_path,start_line,end_line,fingerprint,confidence,evidence_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",fid,id,rule,TITLES.get(rule),rule.startsWith("POL")?"POLICY_DRIFT":"SECURITY",SEVERITY.get(rule),file,start,end,fp,"MEDIUM",evidence);db.jdbc.update("INSERT INTO finding_evidences VALUES(?,?)",fid,mask(code));}
 db.log(id,"SCAN_ACCEPTED","backend","INFO","Signed static analysis received");api.enqueue(id,"SCAN_REQUESTED");events.publish(id.toString());return ResponseEntity.accepted().body(Map.of("scanId",id,"duplicate",false));
 }
}
